<script language="ts">
  import { onMount } from "svelte";
  import { client, clientFile } from "$lib/utils/axiosClient";
  import Swal from "sweetalert2";
  import toast from "$lib/utils/toast";
  import FileSaver from "file-saver";
  import Search from "$lib/components/Search.svelte";
  import Add from "./components/Add.svelte";
  import { showLoader, hideLoader } from "$lib/utils/loading-spinner";
  import Pagination from "$lib/components/Pagination.svelte";
  let newRecord = false;
  let codEstab = "0";

  function openNew(open) {
    newRecord = open;
  }
  let medicalHistories = [],
    establecimientos = [];
  onMount(async () => {
    getEstab();
  });
  const getEstab = async () => {
    debugger;
    showLoader();
    await client
      .get(`EstabAsig/?json=` + JSON.stringify({ tipo: 1 }))
      .then((response) => {
        console.log(response);
        if (response.data.length > 0) {
          establecimientos = response.data;
          if (establecimientos.length > 0) {
            codEstab = establecimientos.find(
              (x) => x.predeterminado == true
            ).codEstab;

            if (codEstab) {
              initialLoad();
            }
          }
        }
        hideLoader();
      })
      .catch((error) => {
        hideLoader();
        console.log(error);
      });
  };

  let recordsQuantity = [10, 25, 50, 100];

  let page = 0;
  let pageCurrent = 0;
  let pageSize = recordsQuantity[0];
  let textSearch = "";
  let timer;

  const initialLoad = async () => {
    medicalHistories = [];
    //showLoader();
    await client
      .get(
        "Vet/MedicalHistories/?json=" +
          JSON.stringify({
            codEstab: codEstab,
            pageIndex: pageCurrent == 0 ? 1 : pageCurrent,
            pageSize: pageSize == 0 ? 9 : pageSize,
            textSearch: textSearch,
          })
      )
      .then((response) => {
        if (response.data.code == "1") {
          medicalHistories = JSON.parse(response.data.payload);
        }
      })
      .catch((error) => {
        //hideLoader();
        console.log(error);
      });
    //hideLoader();
  };

  const onPageChange = (event) => {
    page = event.detail.page;
    pageCurrent = page + 1;
    console.log("one");
    initialLoad();
  };

  const onChange = (e) => {
    pageSize = parseInt(e.target.value);
    console.log("two");
    initialLoad();
  };

  const search = (e) => {
    clearTimeout(timer);
    timer = setTimeout(() => {
      if (e.target.value != "" && e.target.value.length >= 3) {
        textSearch = e.target.value;
        initialLoad();
      } else {
        textSearch = "";
        initialLoad();
      }
    }, 750);
  };

  const clearInput = () => {
    document.querySelector("input").value = "";
    textSearch = "";
    search({ target: { value: "" } });
  };

  const getReport = async (id) => {
    //Add authentication headers as params
    // var params = {
    //     access_token: "An access_token",
    //     other_header: "other_header",
    // };

    //Add authentication headers in URL
    //var url = [url_generating_pdf, $.param(params)].join("?");

    //Open window
    //window.open(url);
    showLoader();
    await clientFile(`Vet/MedicalHistories/Report/` + id)
      .then((response) => {
        var ieEDGE = navigator.userAgent.match(/Edge/g);
        var ie = navigator.userAgent.match(/.NET/g); // IE 11+
        var oldIE = navigator.userAgent.match(/MSIE/g);

        var blob = new window.Blob([response.data], {
          type: "application/pdf",
        });

        if (ie || oldIE || ieEDGE) {
          window.navigator.msSaveBlob(blob, fileName);
        } else {
          var fileURL = URL.createObjectURL(blob);
          window.open(fileURL);
        }
        hideLoader();
        return;
        let fileBlob = new Blob([response.data], {
          type: response.headers["content-type"],
        });
        let objectUrl = window.URL || window.webkitURL;
        let urlFile = objectUrl.createObjectURL(fileBlob);
        // Ajuste horizontal
        let x = parseInt((screen.width - 1200) / 2);
        // Ajustae vertical
        let y = parseInt((screen.height - 650) / 4);
        window.open(
          urlFile,
          "_blank",
          `resizable=yes
					width=1200
					height=650
					screenY=${y}
					screenX=${x}`
        );
        return;
        let serverData = new Blob([response.data], {
          type: response.headers["content-type"],
        });
        // let fileName = response
        //     .headers()["content-disposition"].split(";")[1]
        //     .split("=")[1];
        let fileName = response.headers["content-disposition"]
          .split(";")[1]
          .split("=")[1]
          .replace('"', "");
        fileName = fileName.replace('"', "");
        FileSaver.saveAs(serverData, fileName);
      })
      .catch((error) => {
        hideLoader();
        console.log(error);
      });
  };
  const deleteHistory = async (id) => {
    let { isConfirmed } = await Swal.fire({
      text: "Esta seguro de eliminar este registro?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Si, proceder!",
      cancelButtonText: "No, cancelar",
    });
    if (isConfirmed) {
      await client
        .delete("Vet/MedicalHistories/" + id)
        .then((response) => {
          toast({
            type: "success",
            message: "Eliminada exitosamente",
          });
          medicalHistories = medicalHistories.filter((mh) => mh.id !== id);
        })
        .catch((error) => {
          console.log(error);
        });
    }
  };

  const formatDate = (inputDate) => {
    let date = new Date(inputDate);
    const day = String(date.getDate()).padStart(2, "0");
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const year = String(date.getFullYear());

    return `${day}/${month}/${year}`;
  };

  let searchTerm = "";
  let filteredRecords = [];

  const searchRecords = () => {
    return (filteredRecords = medicalHistories.filter((item) => {
      let petName = item.pet.name.toLowerCase();
      return petName.includes(searchTerm.toLowerCase());
    }));
  };

  let editStatus = false;
  let historyEdited = {};

  const editHistory = (item) => {
    //toast({ type: "info", message: "Funcionalidad en construccion" });
    editStatus = true;
    historyEdited = item;
  };
</script>

<div class="row page-titles">
  <div class="col-md-5 align-self-center">
    <h5 class="text-themecolor">Registro Informado de Estetica Canina</h5>
  </div>
  <div class="col-md-7 align-self-center text-right">
    <div class="d-flex justify-content-end align-items-center">
      <button
        type="button"
        on:click={() => openNew(true)}
        class="btn btn-info d-block d-lg-inline-block m-l-15"
      >
        <i class="fa fa-plus-circle" /> Nuevo
      </button>
    </div>
  </div>
</div>
<!-- <Toaster /> -->
<div class="card">
  <div class="card-body">
    <div class="row">
      <div class="col-xl-4 col-lg-4 col-md-4 col-sm-4 col-12">
        <label for="">Establecimiento:</label>
        <select
          name="codEstab"
          id="codEstab"
          class="form-control"
          required
          bind:value={codEstab}
          on:change={initialLoad}
        >
          <option selected disabled>Seleccione el establecimiento</option>
          {#each establecimientos as item}
            <option value={item.codEstab}>{item.nombreComercial}</option>
          {/each}
        </select>
      </div>
    </div>
  </div>
</div>

{#if newRecord | editStatus}
  <Add {newRecord} {editStatus} {historyEdited} {initialLoad} {codEstab} />
{:else}
  <!-- <Search
		bind:searchTerm
		on:input={searchRecords}
		placeholder="Buscar Mascota"
	/> -->
{/if}

<div class="row">
  <div class="col-lg-9 col-md-9 col-sm-1">
    <span class="form-group pull-left page-size form-inline">
      <select class="form-control control-color" on:change={(e) => onChange(e)}>
        {#each recordsQuantity as record}
          <option value={record}>{record}</option>
        {/each}
      </select>
    </span>
  </div>
  <div class="col-lg-3 col-md-3 col-sm-12 col-12">
    <div class="input-group mb-3">
      <input
        type="text"
        class="form-control form-control-lg search-input"
        placeholder="Buscar..."
        aria-label=""
        aria-describedby="basic-addon1"
        on:keyup={(e) => {
          search(e);
        }}
      />
      <div class="input-group-append">
        <button
          class="btn btn-outline-secondary"
          on:click={() => {
            clearInput();
          }}
          type="button"><i class="fa fa-sync" /></button
        >
      </div>
    </div>
  </div>
</div>
{#if medicalHistories.length > 0}
  <div class="card">
    <div class="card-body">
      <div class="table-responsive">
        <table class="table">
          <thead>
            <tr>
              <th>Cliente</th>
              <th>Mascota</th>
              <th>Fecha</th>
              <th>Edad</th>
              <th>Peso</th>
              <th>Obs</th>
            </tr>
          </thead>
          <tbody>
            {#each medicalHistories as item}
              <tr>
                <td>{item.customer}</td>
                <td>{item.petName}</td>
                <td> {formatDate(item.date)} </td>
                <td>{item.age}</td>
                <td>{item.weight}</td>
                <td> {item.observations} </td>
                <td>
                  <button
                    class="btn btn-outline-danger btn-sm"
                    on:click={deleteHistory(item.id)}
                  >
                    <i class="ti-trash" />
                  </button>
                  <button
                    class="btn btn-outline-warning btn-sm"
                    on:click={editHistory(item)}
                  >
                    <i class="ti-pencil" />
                  </button>
                  <button
                    class="btn btn-outline-danger btn-sm"
                    on:click={getReport(item.id)}
                    title="Obtener Reporte"
                  >
                    <i class="fa fa-file-pdf" />
                  </button>
                </td>
              </tr>
            {/each}
          </tbody>
        </table>
        <!-- Add pagination -->
        <Pagination
          {page}
          {pageSize}
          count={medicalHistories[0]["totalRecords"]}
          on:pageChange={onPageChange}
        />
      </div>
    </div>
  </div>
{:else}
  <h5 class="card-title">No se encontraron registros</h5>
{/if}

